#include <iostream>
#include <string>

class Parent {
public:
    virtual ~Parent() = default;
    virtual void f() const {
        std::cout << "invoke f from Parent\n";
    }
};

class Child : public Parent {
public:
    void f() const override {
        std::cout << "invoke f from Child\n";
    }
};

// Passing by value causes object slicing -> static invocation of Parent::f
void invokeByValue(Parent a) {
    a.f();
}

// Passing by reference allows polymorphic dynamic dispatch
void invokeByReference(const Parent& a) {
    a.f();
}

int main() {
    Parent p;
    Child c;

    std::cout << "--- Call directly ---\n";
    p.f();
    c.f();

    std::cout << "--- Pass by value (Sliced) ---\n";
    invokeByValue(p);
    invokeByValue(c);

    std::cout << "--- Pass by reference (Polymorphic) ---\n";
    invokeByReference(p);
    invokeByReference(c);

    return 0;
}

#include <iostream>

class Base {
public:
    int publicVar{10};
protected:
    int protectedVar{20};
private:
    int privateVar{30};
};

class Derived : public Base {
public:
    void showMembers() const {
        std::cout << "From Derived member function:\n";
        std::cout << "  publicVar: " << publicVar << "\n";
        std::cout << "  protectedVar: " << protectedVar << "\n";
        // std::cout << privateVar; // ERROR: privateVar is private to Base
    }
};

int main() {
    Derived d;
    d.showMembers();

    std::cout << "From external scope (main):\n";
    std::cout << "  d.publicVar = " << d.publicVar << "\n";
    // std::cout << d.protectedVar; // ERROR: cannot access protected member
    // std::cout << d.privateVar;   // ERROR: cannot access private member

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <memory>

// Abstract base class
class GeometricObject {
protected:
    std::string color{"white"};
    bool filled{false};

    GeometricObject() = default;
    GeometricObject(std::string c, bool f) : color(std::move(c)), filled(f) {}

public:
    virtual ~GeometricObject() = default; // Essential for base polymorphic classes

    const std::string& getColor() const { return color; }
    bool isFilled() const { return filled; }

    // Pure virtual functions (= 0)
    virtual double getArea() const = 0;
    virtual double getPerimeter() const = 0;
};

// Concrete derived class
class Rectangle : public GeometricObject {
private:
    double width{1.0};
    double height{1.0};

public:
    Rectangle(double w, double h, std::string c, bool f)
        : GeometricObject(std::move(c), f), width(w), height(h) {}

    double getArea() const override {
        return width * height;
    }

    double getPerimeter() const override {
        return 2 * (width + height);
    }
};

int main() {
    // GeometricObject obj; // Compile error: cannot instantiate abstract class
    Rectangle rect(4.0, 5.0, "blue", true);

    const GeometricObject* geoPtr = &rect;
    std::cout << "Color: " << geoPtr->getColor() << "\n";
    std::cout << "Area: " << geoPtr->getArea() << "\n";
    std::cout << "Perimeter: " << geoPtr->getPerimeter() << "\n";

    return 0;
}
